// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/cryptography/draft-EIP712.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";

/**
 * @title TokenRelayer
 * @dev This contract allows transferring tokens on behalf of users with signature verification.
 *      The signature uses EIP-712 for off-chain message signing.
 */
contract TokenRelayer is EIP712, AccessControl {
    using ECDSA for bytes32;

    // Define a role for executing transfers
    bytes32 public constant TRANSFER_EXECUTOR_ROLE =
        keccak256("TRANSFER_EXECUTOR_ROLE");

    // Nonce mapping for replay protection
    mapping(address => uint256) public nonces;

    // Fee recipient address
    address public feeRecipient;

    // Struct to define the message structure for signing, including a timestamp and fee
    struct TransferRequest {
        address token; // Address of the ERC20 token
        address sender; // Address of the token owner
        address receiver; // Address of the recipient
        uint256 amount; // Token amount to transfer
        uint256 feeAmount; // Fee amount to transfer
        uint256 nonce; // Unique nonce to prevent replay attacks
        bytes32 constantType; // A fixed, user-defined constant
        uint256 timestamp; // Timestamp when the transfer was requested
    }

    // EIP-712 TypeHash for the TransferRequest struct (including feeAmount and timestamp)
    bytes32 private constant TRANSFER_REQUEST_TYPEHASH =
        keccak256(
            "TransferRequest(address token,address sender,address receiver,uint256 amount,uint256 feeAmount,uint256 nonce,bytes32 constantType,uint256 timestamp)"
        );

    // Event emitted when the fee recipient is updated
    event FeeRecipientUpdated(
        address indexed oldFeeRecipient,
        address indexed newFeeRecipient
    );

    // Event emitted when a transfer is executed
    event TransferExecuted(
        address indexed token,
        address indexed sender,
        address indexed receiver,
        uint256 amount,
        uint256 feeAmount,
        uint256 nonce,
        bytes32 constantType,
        uint256 timestamp
    );

    // EIP-712 Domain Separator initialized in the constructor
    constructor(address _feeRecipient) EIP712("TokenRelayer", "1") {
        // Grant the deployer the admin role for managing roles
        _setupRole(DEFAULT_ADMIN_ROLE, msg.sender);
        // Set the fee recipient address during deployment
        feeRecipient = _feeRecipient;
    }

    // Setter function to change the fee recipient address
    function setFeeRecipient(address newFeeRecipient)
        external
        onlyRole(DEFAULT_ADMIN_ROLE)
    {
        address oldFeeRecipient = feeRecipient;
        feeRecipient = newFeeRecipient;
        emit FeeRecipientUpdated(oldFeeRecipient, newFeeRecipient);
    }

    /**
     * @dev Executes a token transfer on behalf of a user after verifying the signature.
     *      Only accounts with the TRANSFER_EXECUTOR_ROLE can call this function.
     * @param token The address of the ERC20 token contract.
     * @param amount The amount of tokens to transfer.
     * @param feeAmount The fee to be deducted from the sender.
     * @param sender The address of the token owner.
     * @param receiver The address of the recipient.
     * @param nonce The unique nonce for this transfer.
     * @param constantType A fixed constant defined by the user.
     * @param timestamp The timestamp when the transfer was signed.
     * @param signature The EIP-712 signature proving sender's authorization.
     */
    function executeTransfer(
        address token,
        uint256 amount,
        uint256 feeAmount,
        address sender,
        address receiver,
        uint256 nonce,
        bytes32 constantType,
        uint256 timestamp,
        bytes memory signature
    ) external onlyRole(TRANSFER_EXECUTOR_ROLE) {
        // Ensure the timestamp is valid
        _validateTimestamp(timestamp);

        // Construct the TransferRequest struct
        TransferRequest memory request = TransferRequest({
            token: token,
            sender: sender,
            receiver: receiver,
            amount: amount,
            feeAmount: feeAmount,
            nonce: nonce,
            constantType: constantType,
            timestamp: timestamp
        });

        // Verify the nonce is correct
        _verifyNonce(sender, nonce);

        // Recover the signer and verify the signature
        _verifySignature(request, signature, sender);

        // Increment the nonce to prevent replay
        nonces[sender]++;

        // Ensure the sender has enough balance for the total amount + fee
        _validateBalance(sender, token, amount, feeAmount);

        // Transfer the tokens (sender -> receiver) and (sender -> feeRecipient)
        _transferTokens(token, sender, receiver, amount, feeAmount);

        emit TransferExecuted(
            token,
            sender,
            receiver,
            amount,
            feeAmount,
            nonce,
            constantType,
            timestamp
        );
    }

    // Private helper function to perform the token transfers
    function _transferTokens(
        address token,
        address sender,
        address receiver,
        uint256 amount,
        uint256 feeAmount
    ) private {
        // Transfer to receiver
        bool successReceiver = IERC20(token).transferFrom(
            sender,
            receiver,
            amount
        );
        require(successReceiver, "Token transfer to receiver failed");

        // Transfer to fee recipient
        bool successFee = IERC20(token).transferFrom(
            sender,
            feeRecipient,
            feeAmount
        );
        require(successFee, "Fee transfer failed");
    }

    /**
     * @dev Recovers the signer address from a TransferRequest and signature.
     * @param token The address of the ERC20 token contract.
     * @param amount The amount of tokens to transfer.
     * @param feeAmount The fee to be deducted from the sender.
     * @param sender The address of the token owner.
     * @param receiver The address of the recipient.
     * @param nonce The unique nonce for this transfer.
     * @param constantType A fixed constant defined by the user.
     * @param timestamp The timestamp when the transfer was signed.
     * @param signature The EIP-712 signature to verify.
     * @return The address of the recovered signer.
     */
    function recoverSigner(
        address token,
        uint256 amount,
        uint256 feeAmount,
        address sender,
        address receiver,
        uint256 nonce,
        bytes32 constantType,
        uint256 timestamp,
        bytes memory signature
    ) external view returns (address) {
        // Construct the TransferRequest struct
        TransferRequest memory request = TransferRequest({
            token: token,
            sender: sender,
            receiver: receiver,
            amount: amount,
            feeAmount: feeAmount,
            nonce: nonce,
            constantType: constantType,
            timestamp: timestamp
        });

        // Hash the struct and recover the signer
        bytes32 digest = _hashTransferRequest(request);
        return digest.recover(signature);
    }

    /**
     * @dev Hash a TransferRequest struct using EIP-712 format.
     * @param request The TransferRequest struct to hash.
     * @return The EIP-712-compliant hash of the struct.
     */
    function _hashTransferRequest(TransferRequest memory request)
        private
        view
        returns (bytes32)
    {
        return
            _hashTypedDataV4(
                keccak256(
                    abi.encode(
                        TRANSFER_REQUEST_TYPEHASH,
                        request.token,
                        request.sender,
                        request.receiver,
                        request.amount,
                        request.feeAmount,
                        request.nonce,
                        request.constantType,
                        request.timestamp
                    )
                )
            );
    }

    // Private helper function to validate timestamp
    function _validateTimestamp(uint256 timestamp) private view {
        require(block.timestamp <= timestamp + 1 hours, "Signature expired");
    }

    // Private helper function to verify nonce
    function _verifyNonce(address sender, uint256 nonce) private view {
        require(nonces[sender] == nonce, "Invalid nonce");
    }

    // Private helper function to verify the signature
    function _verifySignature(
        TransferRequest memory request,
        bytes memory signature,
        address sender
    ) private view {
        bytes32 digest = _hashTransferRequest(request);
        address recoveredSigner = digest.recover(signature);
        require(recoveredSigner == sender, "Invalid signature");
    }

    // Private helper function to validate sender's balance
    function _validateBalance(
        address sender,
        address token,
        uint256 amount,
        uint256 feeAmount
    ) private view {
        uint256 totalAmount = amount + feeAmount;
        uint256 senderBalance = IERC20(token).balanceOf(sender);
        require(senderBalance >= totalAmount, "Insufficient balance");
    }
}

